set
  title = 'Educational Technology',
  goal = 'Educational Technology',
  summary = 'Frame educational technology as purposeful learning design rather than tool use for its own sake. The sequence connects technology choices to how people learn and how teachers design instruction, then covers tool selection, technology-enhanced and blended lessons, digital workflows, multimedia and student production, digital and AI literacy, citizenship and ethics, accessibility, assessment and analytics, emerging tools, privacy and procurement, leadership and implementation, and an evidence-informed capstone design or evaluation.',
